package me.xjanua.aitranswatch.service;
import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import me.xjanua.aitranswatch.dto.vehicle.*; import me.xjanua.aitranswatch.enums.VehicleStatus; import me.xjanua.aitranswatch.model.Vehicle; import me.xjanua.aitranswatch.repository.VehicleRepository;
@Service @Transactional
public class VehicleService {
 private final VehicleRepository repository; public VehicleService(VehicleRepository repository){this.repository=repository;}
 @Transactional(readOnly=true) public Page<VehicleResponse> list(String search,VehicleStatus status,Pageable pageable){ Page<Vehicle> p; boolean has=search!=null&&!search.isBlank(); if(status!=null&&has)p=repository.findByStatusAndLicensePlateContainingIgnoreCaseOrStatusAndVehicleTypeContainingIgnoreCase(status,search,status,search,pageable); else if(status!=null)p=repository.findByStatus(status,pageable); else if(has)p=repository.findByLicensePlateContainingIgnoreCaseOrVehicleTypeContainingIgnoreCase(search,search,pageable); else p=repository.findAll(pageable); return p.map(this::toResponse); }
 @Transactional(readOnly=true) public VehicleResponse get(UUID id){return toResponse(entity(id));}
 public VehicleResponse create(VehicleRequest r){if(repository.existsByLicensePlateIgnoreCase(r.licensePlate()))throw conflict("Biển số xe đã tồn tại"); return toResponse(repository.save(new Vehicle(r.licensePlate(),r.vehicleType(),r.brand(),r.model(),r.manufactureYear(),r.maxPayloadKg(),r.currentOdometerKm(),r.fuelLevelPercent(),r.status(),r.registrationExpiryDate(),r.insuranceExpiryDate(),r.maintenanceIntervalKm(),r.nextMaintenanceOdometerKm())));}
 public VehicleResponse update(UUID id,VehicleRequest r){Vehicle e=entity(id); if(!e.getLicensePlate().equalsIgnoreCase(r.licensePlate())&&repository.existsByLicensePlateIgnoreCase(r.licensePlate()))throw conflict("Biển số xe đã tồn tại"); e.update(r.licensePlate(),r.vehicleType(),r.brand(),r.model(),r.manufactureYear(),r.maxPayloadKg(),r.currentOdometerKm(),r.fuelLevelPercent(),r.status(),r.registrationExpiryDate(),r.insuranceExpiryDate(),r.maintenanceIntervalKm(),r.nextMaintenanceOdometerKm());return toResponse(e);}
 public void deactivate(UUID id){entity(id).deactivate();}
 private Vehicle entity(UUID id){return repository.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy xe"));} private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);} private VehicleResponse toResponse(Vehicle e){return new VehicleResponse(e.getId(),e.getLicensePlate(),e.getVehicleType(),e.getBrand(),e.getModel(),e.getManufactureYear(),e.getMaxPayloadKg(),e.getCurrentOdometerKm(),e.getFuelLevelPercent(),e.getStatus(),e.getRegistrationExpiryDate(),e.getInsuranceExpiryDate(),e.getMaintenanceIntervalKm(),e.getNextMaintenanceOdometerKm());}
}
